  {
    "Name": "CRMAdmin",
    "Key": "ClientRelationshipManagement",
    "ResourceKey": "ClientRelationshipManagement",
    "Script": "CRMAdmin = {
    init: async function (app, container) {
        container = container || $('.component[name=CRMAdmin]');
        try {
            var result = await api.get('ClientRelationshipManagement/AgentRuns?$orderby=CreatedOn desc&$top=10');
            var rows = (result.value || []).map(function (run) {
                return '<tr><td>' + CRMAdmin.escape(run.Lane || run.Source || 'Agent') + '</td><td>' + CRMAdmin.escape(run.Status || (run.Succeeded === true ? 'Succeeded' : run.Succeeded === false ? 'Failed' : 'Unknown')) + '</td><td>' + CRMAdmin.escape(run.CreatedOn || run.StartedOn || '') + '</td></tr>';
            });
            $('[data-crm-agent-runs]', container).html(rows.join('') || '<tr><td colspan="3">No agent runs have been recorded.</td></tr>');
        } catch (_) {
            $('[data-crm-agent-runs]', container).html('<tr><td colspan="3">Agent-run data is unavailable for this user.</td></tr>');
        }
    },
    escape: function (value) {
        return $('<div>').text(value == null ? '' : String(value)).html();
    }
}",
